<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Algorithm Visualizer</title>
  <style>
    :root {
      --bg-primary: #0f172a;
      --bg-secondary: #1e293b;
      --accent-color: #3b82f6;
      --accent-active: #ef4444;
      --accent-success: #10b981;
      --text-main: #f8fafc;
      --text-muted: #94a3b8;
      --border-color: #334155;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background-color: var(--bg-primary);
      color: var(--text-main);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      padding: 20px;
    }

    .container {
      width: 100%;
      max-width: 800px;
      background-color: var(--bg-secondary);
      border: 1px solid var(--border-color);
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
    }

    h1 {
      font-size: 1.5rem;
      font-weight: 700;
      margin-bottom: 20px;
      text-align: center;
      letter-spacing: -0.025em;
    }

    #bars {
      display: flex;
      align-items: flex-end;
      gap: 4px;
      height: 350px;
      background-color: rgba(15, 23, 42, 0.6);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 16px;
      box-sizing: border-box;
      width: 100%;
      margin-bottom: 24px;
      position: relative;
    }

    .bar {
      flex: 1;
      background-color: var(--accent-color);
      border-radius: 4px 4px 0 0;
      transition: height 0.1s ease, background-color 0.1s ease;
      position: relative;
      display: flex;
      justify-content: center;
      align-items: flex-end;
    }

    .bar.active {
      background-color: var(--accent-active);
    }

    .bar.sorted-highlight {
      background-color: var(--accent-success);
    }

    .bar-label {
      font-size: 0.75rem;
      color: var(--text-main);
      margin-bottom: 4px;
      font-weight: 600;
      pointer-events: none;
      z-index: 10;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      justify-content: center;
      align-items: center;
    }

    button {
      background-color: #334155;
      color: var(--text-main);
      border: 1px solid var(--border-color);
      padding: 10px 20px;
      font-size: 0.9rem;
      font-weight: 600;
      border-radius: 6px;
      cursor: pointer;
      transition: all 0.2s ease;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    button:hover:not(:disabled) {
      background-color: #475569;
      border-color: #475569;
    }

    button:active:not(:disabled) {
      transform: scale(0.98);
    }

    button:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    #sort {
      background-color: var(--accent-color);
      border-color: var(--accent-color);
    }

    #sort:hover:not(:disabled) {
      background-color: #2563eb;
    }

    .settings {
      display: flex;
      gap: 16px;
      margin-top: 16px;
      justify-content: center;
      font-size: 0.85rem;
      color: var(--text-muted);
    }

    .setting-item {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    input[type="range"] {
      accent-color: var(--accent-color);
      cursor: pointer;
    }
  </style>
</head>
<body>

  <div class="container">
    <h1>Sorting Visualizer</h1>

    <div id="bars"></div>

    <div class="controls">
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
      <button id="sort">Sort</button>
    </div>

    <div class="settings">
      <div class="setting-item">
        <label for="speed-range">Speed:</label>
        <input type="range" id="speed-range" min="5" max="300" value="50">
      </div>
      <div class="setting-item">
        <label for="size-range">Size:</label>
        <input type="range" id="size-range" min="5" max="50" value="25">
      </div>
    </div>
  </div>

  <script>
    // State management
    let currentArray = [];
    let originalArray = [];
    let i = 0;
    let j = 0;
    let swapped = false;
    let isSorting = false;
    let animTimeoutId = null;

    // Default Configuration
    const speedRange = document.getElementById('speed-range');
    const sizeRange = document.getElementById('size-range');

    function getDelay() {
      // Invert range slider value so higher value is faster
      return 305 - parseInt(speedRange.value);
    }

    function getArraySize() {
      return parseInt(sizeRange.value);
    }

    // Helper: is array fully sorted ascending?
    function isSorted(arr) {
      for (let k = 0; k < arr.length - 1; k++) {
        if (arr[k] > arr[k + 1]) return false;
      }
      return true;
    }

    // Reset loop variables of the Bubble Sort state machine
    function resetSortState() {
      i = 0;
      j = 0;
      swapped = false;
    }

    // Visual Render function
    function renderBars(activeIdx1 = -1, activeIdx2 = -1, isAllSorted = false) {
      const container = document.getElementById('bars');
      container.innerHTML = '';

      if (currentArray.length === 0) return;

      const minVal = Math.min(...currentArray);
      const maxVal = Math.max(...currentArray);
      const range = maxVal - minVal;

      currentArray.forEach((val, idx) => {
        const bar = document.createElement('div');
        bar.className = 'bar';

        // Scale values to elegant visual heights (15% to 100%)
        const pct = range === 0 ? 50 : ((val - minVal) / range) * 85 + 15;
        bar.style.height = `${pct}%`;

        if (isAllSorted) {
          bar.classList.add('sorted-highlight');
        } else if (idx === activeIdx1 || idx === activeIdx2) {
          bar.classList.add('active');
        }

        // Display value if array is small enough
        if (currentArray.length <= 25) {
          const label = document.createElement('span');
          label.className = 'bar-label';
          label.innerText = val;
          bar.appendChild(label);
        }

        container.appendChild(bar);
      });
    }

    // Stop current sorting loop
    function stopAnimation() {
      isSorting = false;
      if (animTimeoutId) {
        clearTimeout(animTimeoutId);
        animTimeoutId = null;
      }
      document.getElementById('sort').disabled = false;
    }

    // Perform exactly one comparison/step of the bubble sort
    function sortStep() {
      if (isSorted(currentArray)) {
        return true;
      }
      if (currentArray.length <= 1) {
        return true;
      }

      if (i >= currentArray.length - 1) {
        return isSorted(currentArray);
      }

      const idx1 = j;
      const idx2 = j + 1;

      if (currentArray[idx1] > currentArray[idx2]) {
        const temp = currentArray[idx1];
        currentArray[idx1] = currentArray[idx2];
        currentArray[idx2] = temp;
        swapped = true;
      }

      renderBars(idx1, idx2);

      j++;
      if (j >= currentArray.length - 1 - i) {
        j = 0;
        if (!swapped) {
          i = currentArray.length; // triggers exit on next step
        }
        swapped = false;
        i++;
      }

      return isSorted(currentArray);
    }

    // Generate a random array
    function generateRandomArray() {
      const size = getArraySize();
      const arr = [];
      for (let k = 0; k < size; k++) {
        // Random numbers between 5 and 100
        arr.push(Math.floor(Math.random() * 95) + 5);
      }
      currentArray = [...arr];
      originalArray = [...arr];
      resetSortState();
      renderBars();
    }

    // Main animation runner
    function startSorting() {
      if (isSorting) return;
      isSorting = true;
      document.getElementById('sort').disabled = true;

      function loop() {
        if (!isSorting) return;
        const done = sortStep();
        if (done) {
          isSorting = false;
          document.getElementById('sort').disabled = false;
          renderBars(-1, -1, true); // final render with success state
        } else {
          animTimeoutId = setTimeout(loop, getDelay());
        }
      }
      loop();
    }

    // Set up Programmatic API on window
    window.viz = {
      array() {
        return currentArray;
      },
      setArray(a) {
        stopAnimation();
        currentArray = [...a];
        originalArray = [...a];
        resetSortState();
        renderBars();
      },
      sortStep() {
        return sortStep();
      },
      sorted() {
        return isSorted(currentArray);
      }
    };

    // UI Event Listeners
    document.getElementById('shuffle').addEventListener('click', () => {
      stopAnimation();
      generateRandomArray();
    });

    document.getElementById('reset').addEventListener('click', () => {
      stopAnimation();
      currentArray = [...originalArray];
      resetSortState();
      renderBars();
    });

    document.getElementById('sort').addEventListener('click', () => {
      if (isSorted(currentArray)) {
        renderBars(-1, -1, true);
        return;
      }
      startSorting();
    });

    sizeRange.addEventListener('input', () => {
      stopAnimation();
      generateRandomArray();
    });

    // Initialize UI
    generateRandomArray();
  </script>
</body>
</html>
